# Size overview + look for secrets / heavy dirs
Get-ChildItem -Directory | ForEach-Object {
  $size = (Get-ChildItem $_.FullName -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
  [PSCustomObject]@{ Name = $_.Name; SizeMB = [math]::Round($size/1MB, 1) }
} | Sort-Object SizeMB -Descending | Format-Table -AutoSize

Write-Host "=== Sensitive / heavy patterns ==="
Get-ChildItem -Recurse -Force -ErrorAction SilentlyContinue | Where-Object {
  $_.Name -match '^\.env|\.pem$|\.key$|credentials|secret|password|\.git$|node_modules|\.venv|__pycache__|\.next|dist$|build$'
} | Select-Object -First 80 FullName | ForEach-Object { $_.FullName.Replace((Get-Location).Path + '\', '') }

# Find all nested .git, env files, credentials, large binary-ish stuff at top level of each project
Write-Host "=== Nested .git ==="
Get-ChildItem -Recurse -Directory -Force -Filter ".git" -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName.Replace((Get-Location).Path + '\', '') }

Write-Host "`n=== .env / credentials / keys (excluding venv/node_modules) ==="
Get-ChildItem -Recurse -Force -File -ErrorAction SilentlyContinue | Where-Object {
  $p = $_.FullName
  if ($p -match '\\(\.venv|venv|node_modules|\.git|__pycache__|site-packages)\\') { return $false }
  $_.Name -match '^\.env|\.pem$|\.key$|credential|secret|\.p12$|\.pfx$|id_rsa|token\.json|service.account' -or
  $_.Extension -match '^\.(env|pem|key)$'
} | ForEach-Object { 
  "$([math]::Round($_.Length/1KB,1))KB  $($_.FullName.Replace((Get-Location).Path + '\', ''))"
}

Write-Host "`n=== Top-level heavy dirs to ignore ==="
@('node_modules','.venv','venv','__pycache__','dist','build','.next','.nuxt','target','vendor') | ForEach-Object {
  $name = $_
  $dirs = Get-ChildItem -Recurse -Directory -Force -Filter $name -ErrorAction SilentlyContinue | Where-Object { $_.FullName -notmatch '\\(\.venv|venv|node_modules|\.git)\\' }
  if ($dirs) { Write-Host "$name : $($dirs.Count) dirs" }
}

# What's big in the largest folders (top-level only, one level deep sizes)
function Get-DirSizes($path) {
  Get-ChildItem $path -Force -ErrorAction SilentlyContinue | ForEach-Object {
    if ($_.PSIsContainer) {
      $s = (Get-ChildItem $_.FullName -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
    } else { $s = $_.Length }
    [PSCustomObject]@{ Name = $_.Name; MB = [math]::Round(($s/1MB),1) }
  } | Sort-Object MB -Descending | Select-Object -First 15
}

Write-Host "=== 1688自动化 ==="; Get-DirSizes "1688自动化" | Format-Table -AutoSize
Write-Host "=== EasyHermes ==="; Get-DirSizes "EasyHermes-飞书表格，本地干活" | Format-Table -AutoSize
Write-Host "=== 清泉跨境系统 ==="; Get-DirSizes "清泉跨境系统（企业级）" | Format-Table -AutoSize
Write-Host "=== temu ==="; Get-DirSizes "temu" | Format-Table -AutoSize
Write-Host "=== 亚马逊 ==="; Get-DirSizes "亚马逊平台驾驶舱" | Format-Table -AutoSize
Write-Host "=== AIc ==="; Get-DirSizes "AIc" | Format-Table -AutoSize

# Any files > 50MB?
Write-Host "=== Files > 50MB (excl venv/node_modules) ==="
Get-ChildItem -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object {
  $_.Length -gt 50MB -and $_.FullName -notmatch '\\(\.venv|venv|node_modules|site-packages)\\'
} | ForEach-Object { "$([math]::Round($_.Length/1MB,1))MB  $($_.FullName.Replace((Get-Location).Path+'\',''))" }

Write-Host "=== 清泉 backend ==="; 
Get-ChildItem "清泉跨境系统（企业级）\backend" -Force -ErrorAction SilentlyContinue | ForEach-Object {
  if ($_.PSIsContainer) { $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum } else { $s = $_.Length }
  [PSCustomObject]@{ Name = $_.Name; MB = [math]::Round($s/1MB,1) }
} | Sort-Object MB -Descending | Select-Object -First 12 | Format-Table -AutoSize

Write-Host "=== 清泉 web ==="
Get-ChildItem "清泉跨境系统（企业级）\web" -Force -ErrorAction SilentlyContinue | ForEach-Object {
  if ($_.PSIsContainer) { $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum } else { $s = $_.Length }
  [PSCustomObject]@{ Name = $_.Name; MB = [math]::Round($s/1MB,1) }
} | Sort-Object MB -Descending | Select-Object -First 12 | Format-Table -AutoSize

Write-Host "=== temu-monitor ==="
Get-ChildItem "temu\temu-monitor" -Force -ErrorAction SilentlyContinue | ForEach-Object {
  if ($_.PSIsContainer) { $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum } else { $s = $_.Length }
  [PSCustomObject]@{ Name = $_.Name; MB = [math]::Round($s/1MB,1) }
} | Sort-Object MB -Descending | Select-Object -First 12 | Format-Table -AutoSize

Write-Host "=== ship-sentinel ==="
Get-ChildItem "AIc\ship-sentinel" -Force -ErrorAction SilentlyContinue | ForEach-Object {
  if ($_.PSIsContainer) { $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum } else { $s = $_.Length }
  [PSCustomObject]@{ Name = $_.Name; MB = [math]::Round($s/1MB,1) }
} | Sort-Object MB -Descending | Select-Object -First 12 | Format-Table -AutoSize

Write-Host "=== 1688 商品数据 sample ==="
Get-ChildItem "1688自动化\商品数据" -Force -EA SilentlyContinue | Select-Object -First 10 Name, @{N='MB';E={[math]::Round($_.Length/1MB,1)}}
Write-Host "file count:" (Get-ChildItem "1688自动化\商品数据" -Recurse -File -EA SilentlyContinue | Measure-Object).Count

Write-Host "=== Existing root gitignores ==="
Get-ChildItem -Recurse -Force -Filter ".gitignore" -EA SilentlyContinue | Where-Object { $_.FullName -notmatch '\\(\.venv|node_modules)\\' } | ForEach-Object { $_.FullName.Replace((Get-Location).Path+'\','') }

# Rename nested .git so parent can track their files as normal directories
$nested = @(
  'Chinese-PhoenixCrown\.git',
  'multi-agent-async-workflow\.git',
  'temu\.git',
  '亚马逊平台驾驶舱\.git',
  '海外TK店铺广告投流数据自动化监测\.git',
  '海外仓\.git',
  '清泉跨境系统（企业级）\.git'
)
foreach ($p in $nested) {
  if (Test-Path $p) {
    $dest = $p + '.bak'
    if (Test-Path $dest) { Remove-Item $dest -Recurse -Force }
    Rename-Item $p '.git.bak'
    Write-Host "Renamed $p -> .git.bak"
  } else {
    Write-Host "Missing: $p"
  }
}

# Also add .git.bak to gitignore is already done
Write-Host "`n=== Verify no nested .git remain ==="
Get-ChildItem -Recurse -Directory -Force -Filter ".git" -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName }

# Find Claude Code / Grok related dirs and files under E:\project
Write-Host "=== Top-level hidden / special dirs ==="
Get-ChildItem -Force | Where-Object { $_.Name -match '^\.|claude|grok|cursor|windsurf|copilot|memory|chat|conversation|transcript' } | Select-Object Mode, Name

Write-Host "`n=== .claude dirs anywhere under project ==="
Get-ChildItem -Recurse -Directory -Force -ErrorAction SilentlyContinue | Where-Object {
  $_.Name -match '^\.claude$|^claude$|grok|memory|\.cursor|\.codex|agent-transcript|conversation'
} | ForEach-Object {
  $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum
  "{0,8:N1} MB  {1}" -f ($s/1MB), $_.FullName.Replace((Get-Location).Path+'\','')
}

Write-Host "`n=== Files matching claude/grok/memory/session patterns ==="
Get-ChildItem -Recurse -Force -File -ErrorAction SilentlyContinue | Where-Object {
  $_.FullName -notmatch '\\(\.venv|venv|node_modules|site-packages|\.git)\\' -and
  (
    $_.Name -match 'claude|grok|MEMORY|memory\.md|CLAUDE\.md|\.claude' -or
    $_.DirectoryName -match '\\\.claude\\|\\memory\\'
  )
} | Select-Object -First 100 | ForEach-Object {
  "{0,8:N1} KB  {1}" -f ($_.Length/1KB), $_.FullName.Replace((Get-Location).Path+'\','')
}

Write-Host "=== User home Claude / Grok locations ==="
$paths = @(
  "$env:USERPROFILE\.claude",
  "$env:USERPROFILE\.config\claude",
  "$env:USERPROFILE\.grok",
  "$env:USERPROFILE\.config\grok",
  "$env:APPDATA\Claude",
  "$env:APPDATA\Grok",
  "$env:LOCALAPPDATA\Claude",
  "$env:LOCALAPPDATA\Grok",
  "$env:USERPROFILE\.cursor",
  "C:\Users\Administrator\.claude"
)
foreach ($p in $paths) {
  if (Test-Path $p) {
    $s = (Get-ChildItem $p -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum
    "{0,8:N1} MB  {1}" -f ($s/1MB), $p
  }
}

Write-Host "`n=== ~/.claude structure ==="
if (Test-Path "$env:USERPROFILE\.claude") {
  Get-ChildItem "$env:USERPROFILE\.claude" -Force | ForEach-Object {
    if ($_.PSIsContainer) {
      $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum
      "DIR  {0,8:N1} MB  {1}" -f ($s/1MB), $_.Name
    } else {
      "FILE {0,8:N1} KB  {1}" -f ($_.Length/1KB), $_.Name
    }
  }
}

Write-Host "`n=== projects under .claude ==="
if (Test-Path "$env:USERPROFILE\.claude\projects") {
  Get-ChildItem "$env:USERPROFILE\.claude\projects" -Force | ForEach-Object {
    $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum
    "{0,8:N1} MB  {1}" -f ($s/1MB), $_.Name
  }
}

Write-Host "=== .claude/projects related to E-project ==="
Get-ChildItem "$env:USERPROFILE\.claude\projects" -Force | Where-Object { $_.Name -match 'E--project|project' } | ForEach-Object {
  $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum
  $fc = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object).Count
  "{0,8:N1} MB  {1,5} files  {2}" -f ($s/1MB), $fc, $_.Name
}

Write-Host "`n=== Sample structure of largest project dirs ==="
foreach ($d in @('E--project','E--project------------','E--project-temu','E--project----')) {
  $p = Join-Path "$env:USERPROFILE\.claude\projects" $d
  if (Test-Path $p) {
    Write-Host "`n--- $d ---"
    Get-ChildItem $p -Force | Select-Object -First 20 | ForEach-Object {
      if ($_.PSIsContainer) {
        $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum
        "  DIR  {0,7:N1} MB  {1}" -f ($s/1MB), $_.Name
      } else {
        "  FILE {0,7:N1} KB  {1}" -f ($_.Length/1KB), $_.Name
      }
    }
  }
}

Write-Host "`n=== memory dirs ==="
Get-ChildItem "$env:USERPROFILE\.claude\projects" -Recurse -Directory -Force -Filter "memory" -EA SilentlyContinue | ForEach-Object {
  $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum
  "{0,8:N1} MB  {1}" -f ($s/1MB), $_.FullName.Replace("$env:USERPROFILE\.claude\projects\",'')
}

Write-Host "`n=== .grok structure ==="
Get-ChildItem "$env:USERPROFILE\.grok" -Force | ForEach-Object {
  if ($_.PSIsContainer) {
    $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum
    "DIR  {0,8:N1} MB  {1}" -f ($s/1MB), $_.Name
  } else {
    "FILE {0,8:N1} KB  {1}" -f ($_.Length/1KB), $_.Name
  }
}

Write-Host "=== Grok sessions ==="
Get-ChildItem "$env:USERPROFILE\.grok\sessions" -Force | ForEach-Object {
  if ($_.PSIsContainer) {
    $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum
    "DIR  {0,8:N1} MB  {1}" -f ($s/1MB), $_.Name
  } else {
    "FILE {0,8:N1} KB  {1}" -f ($_.Length/1KB), $_.Name
  }
} | Select-Object -First 40

Write-Host "`n=== Grok memtrace ==="
Get-ChildItem "$env:USERPROFILE\.grok\memtrace" -Recurse -Force -EA SilentlyContinue | Select-Object -First 20 FullName, Length

Write-Host "`n=== Grok logs sample ==="
Get-ChildItem "$env:USERPROFILE\.grok\logs" -Force | Select-Object -First 10 Name, @{N='KB';E={[math]::Round($_.Length/1KB,1)}}

Write-Host "`n=== Total Claude E--project* size ==="
$claudeProj = Get-ChildItem "$env:USERPROFILE\.claude\projects" -Force | Where-Object { $_.Name -like 'E--project*' }
$claudeSize = ($claudeProj | ForEach-Object { (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum } | Measure-Object -Sum).Sum
$claudeFiles = ($claudeProj | ForEach-Object { (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object).Count } | Measure-Object -Sum).Sum
"Claude E-project*: {0:N1} MB, {1} files, {2} project dirs" -f ($claudeSize/1MB), $claudeFiles, $claudeProj.Count

Write-Host "`n=== Claude global memory-ish files ==="
@('history.jsonl','settings.json','config.json') | ForEach-Object {
  $p = Join-Path "$env:USERPROFILE\.claude" $_
  if (Test-Path $p) { "{0,8:N1} KB  {1}" -f ((Get-Item $p).Length/1KB), $_ }
}

Write-Host "`n=== Check for path/cwd metadata in a sample session (first lines) ==="
$sample = Get-ChildItem "$env:USERPROFILE\.claude\projects\E--project------------" -Filter "*.jsonl" -File | Sort-Object Length -Descending | Select-Object -First 1
if ($sample) {
  Write-Host "Sample: $($sample.Name) size=$([math]::Round($sample.Length/1MB,1))MB"
  Get-Content $sample.FullName -TotalCount 1 | ForEach-Object { $_.Substring(0, [Math]::Min(500, $_.Length)) }
}

Write-Host "`n=== Grok session file types ==="
Get-ChildItem "$env:USERPROFILE\.grok\sessions" -Recurse -File -Force -EA SilentlyContinue |
  Group-Object Extension | Sort-Object Count -Descending |
  Select-Object -First 15 @{N='Ext';E={if($_.Name){$_.Name}else{'(none)'}}}, Count, @{N='MB';E={[math]::Round(($_.Group | Measure-Object Length -Sum).Sum/1MB,1)}}

Write-Host "`n=== Any files > 50MB in claude project or grok sessions ==="
@(
  (Get-ChildItem "$env:USERPROFILE\.claude\projects" -Recurse -File -Force -EA SilentlyContinue | Where-Object { $_.FullName -match 'E--project' -and $_.Length -gt 50MB }),
  (Get-ChildItem "$env:USERPROFILE\.grok\sessions" -Recurse -File -Force -EA SilentlyContinue | Where-Object { $_.Length -gt 50MB })
) | ForEach-Object { $_ } | ForEach-Object { "{0:N1} MB  {1}" -f ($_.Length/1MB), $_.FullName.Replace("$env:USERPROFILE\",'') }

# Peek settings / auth for secrets before copying
Write-Host "=== claude settings.json ==="
Get-Content "$env:USERPROFILE\.claude\settings.json" -Raw -EA SilentlyContinue
Write-Host "`n=== grok config.toml ==="
Get-Content "$env:USERPROFILE\.grok\config.toml" -Raw -EA SilentlyContinue
Write-Host "`n=== grok auth.json (redact values) ==="
if (Test-Path "$env:USERPROFILE\.grok\auth.json") {
  Get-Content "$env:USERPROFILE\.grok\auth.json" -Raw | ForEach-Object {
    $_ -replace '(:\s*")[^"]{8,}(")', '$1***REDACTED***$2'
  }
}
Write-Host "`n=== Grok project session total ==="
$gs = Get-ChildItem "$env:USERPROFILE\.grok\sessions" -Directory -Force | Where-Object { $_.Name -like 'E%3A%5Cproject*' -or $_.Name -like '*project*' }
$gs | ForEach-Object {
  $s = (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum
  "{0,8:N1} MB  {1}" -f ($s/1MB), [uri]::UnescapeDataString($_.Name)
}
$gt = ($gs | ForEach-Object { (Get-ChildItem $_.FullName -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum } | Measure-Object -Sum).Sum
"Grok E-project sessions total: {0:N1} MB" -f ($gt/1MB)

Write-Host "`n=== plans dir ==="
if (Test-Path "$env:USERPROFILE\.claude\plans") {
  Get-ChildItem "$env:USERPROFILE\.claude\plans" -Force | Select-Object Name, @{N='KB';E={[math]::Round($_.Length/1KB,1)}}
}

Write-Host "`n=== file-history related? ==="
Get-ChildItem "$env:USERPROFILE\.claude\file-history" -Force -EA SilentlyContinue | Select-Object -First 5 Name
# count
$fh = (Get-ChildItem "$env:USERPROFILE\.claude\file-history" -Recurse -File -Force -EA SilentlyContinue | Measure-Object Length -Sum)
"file-history: {0:N1} MB, {1} files" -f ($fh.Sum/1MB), $fh.Count
